"""
No-answer accuracy and abstention evaluation metrics.
"""

from __future__ import annotations

import re

# Standard refusal phrases generated by the prompt / LLM when information is missing
ABSTENTION_PATTERNS: list[str] = [
    r"do not contain sufficient information",
    r"does not contain sufficient information",
    r"not mentioned in the provided",
    r"not mentioned in the context",
    r"cannot be answered based on the provided",
    r"cannot be determined from the provided",
    r"no information provided",
    r"not provided in the source",
    r"insufficient information",
    r"i am unable to answer",
    r"i cannot answer",
]


def is_abstention(answer: str) -> bool:
    """
    Check if the generated response clearly abstains due to lack of evidence.
    """
    if not answer or not answer.strip():
        return False

    lower_ans = answer.lower().strip()
    for pattern in ABSTENTION_PATTERNS:
        if re.search(pattern, lower_ans):
            return True

    return False


def evaluate_no_answer(answer: str, answerable: bool) -> tuple[bool, float]:
    """
    Evaluate response for unanswerable questions.

    Args:
        answer: Generated text.
        answerable: Ground truth answerability.

    Returns:
        tuple of (is_correct_abstention, score)
        For answerable=False:
            If answer abstains: (True, 1.0)
            If answer attempts to answer: (False, 0.0)
        For answerable=True:
            If answer does NOT abstain: (True, 1.0)
            If answer improperly abstains: (False, 0.0)
    """
    abstains = is_abstention(answer)
    if not answerable:
        return (abstains, 1.0 if abstains else 0.0)
    else:
        # If it is answerable, proper behavior is not to abstain
        return (not abstains, 1.0 if not abstains else 0.0)
